        {
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Voi dovete adorar Dio per sottrarvi all'arbitrio e alla prepotenza degli uomini.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Dio e il Popolo.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Due gioie concesse Iddio agli uomini liberi sulla terra: il plauso dei buoni, e la bestemmia dei tristi!", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Finché, domestica o straniera, voi avete tirannide, come potete aver patria? La patria è la casa dell'uomo, non dello schiavo.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "I popoli imparano più da una sconfitta, che non i re dal trionfo.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Il mondo non è uno Spettacolo, è una arena di battaglia.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La disperazione e l'ateismo sono una stessa cosa.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La neutralità per la politica italiana significa oscurità politica, nullità in Europa, perpetuo pericolo di invasione.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Oggi ciò che importa anzitutto è \"moralizzare\" l'Italia.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Pensiero e Azione.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Prima condizione per riuscire in una grande impresa è il definirla, il vederne chiaro l'intento.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Voi avete dato il primo e più potente grido di rigenerazione!", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La coscienza dell'umanità è suprema su tutti i governi: essi devono esserne interpreti, o non sono legittimi.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La coscienza umana ha decretato che il governo di Napoli, il governo del papa, il governo dell'Austria in Italia hanno meritato perire. Chi vibra il colpo è esecutore di quel santo decreto.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Cerchiamo, vogliamo la patria. La volete voi pure?", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Lasciateci fare. Che importa a voi, qual rìschio correte se i battelli che salpano per Sicilia piegano a mezza via, verso le terre napoletane o romane?", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "A parole chiare, risposta chiara. Non cederemo. Noi siamo forti e ostinati. Abbiamo per noi l'istinto della gioventù, del popolo d'Italia.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Vogliamo la patria, la patria una e rapidamente. Possiamo cedere su tutto; su questo no. Potete, sapete darcela?", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Diremo, come un tempo, clandestinamente il vero all'Italia, che finirà per intenderlo. Potete imprigionare taluni fra noi: sorgeranno altri a continuare l'opera nostra.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Dio esiste. Noi non dobbiamo né vogliamo provarvelo: tentarlo ci sembrerebbe bestemmia, come negarlo, follia.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La vita d'un'anima è sacra, in ogni suo periodo: nel periodo terreno come negli altri che seguiranno.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La famiglia è la Patria del core.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La Famiglia è concetto di Dio, non vostro. Potenza umana non può sopprimerla. Come la Patria, più assai che la Patria, la Famiglia è un elemento della vita.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Amate, rispettate la donna. Non cercate in essa solamente un conforto, ma una forza, una ispirazione, un raddoppiamento delle vostre facoltà intellettuali e morali.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Amate i figli che la Provvidenza vi manda; ma amateli di vero, profondo, severo amore; non dell'amore snervato, irragionevole, cieco, ch'è egoismo per voi, rovina per essi.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Amate i parenti. La Famiglia che procede da voi non vi faccia mai dimenticare la famiglia dalla quale procedete.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Le Idee, cacciate una volta che siano nel mondo dell'intelletto, non muoiono più. Altri le raccoglie, anche dimenticandone la sorgente.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Oggi sappiamo che la legge della Vita è PROGRESSO.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La libertà non è che un \"mezzo\"; guai a voi e al vostro avvenire se v'avvezzaste mai a guardarla siccome fine!", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Non bisogna abolire la proprietà perché oggi è di \"pochi\"; bisogna aprire la via perché i \"molti\" possano acquistarla.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Cielo e Mare – due simboli dell'infinito e, coll'Alpi, le più sublimi cose che la natura ci mostri.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Ci affratellammo della saldissima tra le amicizie, che è quella santificata dall'unità d'un intento buono.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La Vita è Missione; e quindi il Dovere è la sua legge suprema.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "SIRE! S'io vi credessi re volgare, d'anima inetta o tirannica, non v'indirizzerei la parola dell'uomo libero. I re di tal tempra non lasciano al cittadino che la scelta fra l'armi e il silenzio.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Ma voi, SIRE, non siete tale. La natura, creandovi al trono v'ha creato pure a' grandi concetti ed a' forti pensieri; e l'Italia sa che voi avete di regio più che la porpora.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La verità non è linguaggio di cortigiano: non suona che sul labbro di chi né spera, né teme dalla potenza.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "La Federazione della Giovine Italia data l'era sua dall'anno 1831. Essa ha per iscopo: 1°. La repubblica, una, indivisibile, in tutto il territorio italiano, indipendente, uno e libero.", Author = "Giuseppe Mazzini" },
            new Quote { Id = "https://it.wikiquote.org/wiki/Giuseppe_Mazzini", Text = "Il suo repubblicanesimo nacque anche dalla persuasione che l'Italia potesse unificarsi solo abbattendo le sue dinastie.", Author = "Giuseppe Mazzini" },
